input.command:
cd ~/.local/share/public && M=$(mktemp -d /tmp/public.XXXXXX) && run() { mut=$1; shift; mkdir "$M/$mut" && cp -R public "$M/$mut/"; L="$M/$UNKNOWN.sh"; "$@" "$L"; n=$(cd "$M/$mut" && ruby public.rb --smoke 2>&1 | rg -c 'public.sh: (bash|zsh) smoke'); printf '%-10s errors=%s\n' "$mut" "${n:-0}"; }
del() { sed -i '' "${N}d" "$1"; }
for N in 17 18 19 20 22 23 24 25 28 29 30 31 32 33; do run item$N del & done; wait
move() { awk -v s=$S 'NR==s{next} NR==17{print line} {print}' line="$(sed -n "${S}p" "$1")" "$1" > "$1.n" && mv "$1.n" "$1"; }
for S in 28 29 30 32 33; do (S=$S; run other$S move) & done; wait
